import ast
import io
import json
import zipfile
from pathlib import Path

from .formal import explore
from .specification import spec_hash


def generate(spec):
    digest = spec_hash(spec)
    engine = Path(__file__).with_name("engine.py").read_text()
    machine = (
        f'# Generated by Payment Proof Lab. Specification SHA-256: {digest}\n'
        '# Standalone Python 3.11+. Do not edit; regenerate from the specification.\n'
        + engine + '\n\nimport json\n'
        + f'SPEC_HASH = {digest!r}\n'
        + f'SPEC = json.loads({json.dumps(spec, ensure_ascii=False)!r})\n\n'
        + 'def transition(state, event, inputs=None):\n'
        + '    return step(SPEC, state, event, inputs)\n\n'
        + 'def new_monitor(state=None, seen=None):\n'
        + '    return Monitor(SPEC, state, seen)\n'
    )
    # Validate generated syntax before returning or executing an artifact.
    ast.parse(machine)
    graph = explore(spec)
    vectors = [{"before": graph["nodes"][e["source"]]["state"], "event": e["event"], "inputs": e["inputs"],
                "after": graph["nodes"][e["target"]]["state"]}
               for e in graph["edges"] if e["event"] != "stutter"]
    tests = (
        '"""Generated transition vectors; these do not prove generator correctness."""\n'
        'import json\nimport unittest\n'
        'from payment_machine import transition\n\n'
        f'VECTORS = json.loads({json.dumps(vectors, ensure_ascii=False)!r})\n\n'
        'class GeneratedTests(unittest.TestCase):\n'
        '    def test_transition_vectors(self):\n'
        '        for vector in VECTORS:\n'
        '            with self.subTest(event=vector["event"], state=vector["before"]):\n'
        '                self.assertEqual(transition(vector["before"], vector["event"], vector["inputs"]),\n'
        '                                 vector["after"])\n\n'
        'if __name__ == "__main__":\n    unittest.main()\n'
    )
    return {"spec_hash": digest, "files": {
        "payment_machine.py": machine,
        "payment_monitor.py": 'from payment_machine import new_monitor, SPEC_HASH\n\n'
                              '# Persist monitor.state and monitor.seen atomically per order.\n'
                              'monitor = new_monitor()\n',
        "test_payment_generated.py": tests,
        "specification.json": json.dumps(spec, indent=2, ensure_ascii=False),
        "README.md": f"# Generated payment artifact\n\nSpecification: `{digest}`\n\n"
                     "Run `python -m unittest test_payment_generated.py`. No third-party dependencies.\n\n"
                     "Use `transition()` for raw semantics; `new_monitor()` adds enforcement and event deduplication.\n"
                     "Callers must authenticate events and persist state plus event IDs atomically.\n"
                     "Generated vectors check sample transitions, not independent correctness of the generator.\n"
                     "Generation is not certification: run the checker and integration tests.\n"
    }, "vector_count": len(vectors), "vectors_complete": graph["complete"]}


def load_machine(artifact):
    namespace = {"__name__": "generated_payment_machine"}
    # Only locally generated code is accepted, never uploaded Python. Spec data is JSON in a quoted literal.
    exec(compile(artifact["files"]["payment_machine.py"], "payment_machine.py", "exec"), namespace)  # noqa: S102
    return namespace


def archive(artifact):
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", zipfile.ZIP_DEFLATED) as bundle:
        for name, source in artifact["files"].items():
            bundle.writestr(name, source)
    return stream.getvalue()
